create table d_trd_option_deal_settlement(key_otc_trade_id string comment '内部合约ID',contract_initial_price string comment '合约期初价格',contract_maturity_price string comment '合约期末价格',actual_time_to_maturity string comment '实际期限（天）',actual_premium_date string comment '期权费实际支付日',actual_payment_date string comment '实际兑付日',floating_rate string comment '浮动收益率（%）',fix_pnl string comment '固定收益（元）',floating_pnl string comment '浮动收益（元）',settlement_amount string comment '结算金额（元）',net_pnl string comment '交易净收取（元）',remark string comment '备注',actual_settlement_date string comment '实际结算日：AUTOCALL敲出则为敲出观察日，否则为期末定价日',created_datetime string comment '创建时间',created_by string comment '创建人',updated_datetime string comment '修改时间',updated_by string comment '修改人',termination_date_pv string comment '终止日PV',termination_intrinsic_value string comment '【AI】终止内在价值',data_time string comment '【AI】数据时间') partitioned by (busi_date string) row format delimited fields terminated by ',' stored as textfile;
